def solution(volumes, target):
    best_start, best_len = -1, -1
    total = 0
    left = 0
    for right, v in enumerate(volumes):
        total += v
        while total >= target:
            length = right - left + 1
            if best_len == -1 or length < best_len:
                best_start, best_len = left + 1, length
            total -= volumes[left]
            left += 1
    return [best_start, best_len]
